<?php declare(strict_types=1);
function ownEmailAddressBrowser(PDO $db,string $authKey):array
{
 $cfg=\Kulturhus\Native\TestSupport::config();$root=dirname(getenv('KH_NATIVE_TEST_CONFIG')).'/email-address-browser-'.$cfg['database'];mkdir($root,0700);foreach(['web','media','manager-sessions']as$dir)mkdir($root.'/'.$dir,0700);file_put_contents($root.'/auth.key',$authKey);chmod($root.'/auth.key',0600);file_put_contents($root.'/private.key',random_bytes(32));chmod($root.'/private.key',0600);putenv('KH_NATIVE_AUTH_KEY_FILE='.$root.'/auth.key');putenv('KH_NATIVE_PRIVATE_KEY_FILE='.$root.'/private.key');$nativeRoot=dirname(getenv('KH_NATIVE_TEST_CONFIG')).'/runtime-'.$cfg['database'];if(!is_dir($nativeRoot))mkdir($nativeRoot,0700);file_put_contents($nativeRoot.'/auth.key',$authKey);chmod($nativeRoot.'/auth.key',0600);$auth=new \Kulturhus\Native\Auth\Service($db,$authKey);$password='Own browser address password 2026!';$actors=[];$clubs=[];
 foreach(['native','integrated']as$mode)foreach(['js','basic']as$flow){
  $id='address-browser-'.$mode.'-'.$flow;
  if($mode==='integrated'){\Kulturhus\Native\Shared\Db::run($db,'INSERT INTO clubs VALUES(?,?)',[$id,'Own address browser '.$flow]);\Kulturhus\Native\Shared\Db::run($db,'INSERT INTO actors(id,club_id,role,is_superuser) VALUES(?,?,\'members\',1)',[$id,$id]);$bridge=new \Kulturhus\Native\Integration\ManagerBridge($db,$id,'native',static fn()=>null);$access=$bridge->access();$actor=$access->user()['id'];}
  else{$access=new \Kulturhus\Native\Shared\Access($db,'admin');$actor=$id;\Kulturhus\Native\Shared\Db::run($db,"INSERT INTO native_users(id,club_id,name) VALUES(?,'synthetic-a',?)",[$actor,'Own native address '.$flow]);}
  $club=$access->club();if(!in_array($club,$clubs,true)){\Kulturhus\Native\Shared\Db::run($db,'INSERT INTO native_club_settings VALUES(?,1,?,?,UTC_TIMESTAMP()) ON DUPLICATE KEY UPDATE payload=VALUES(payload)',[$club,json_encode(['name'=>'Own browser address club','origin'=>'https://account-address.example.invalid','address'=>'','logo_id'=>''],JSON_THROW_ON_ERROR),$access->user()['id']]);$clubs[]=$club;}
  $email=$id.'@example.invalid';$invite=$auth->createInvitation($access,$actor,$email,86400,$id);$auth->acceptInvitation($invite['token'],$password);$login=$auth->passwordLogin($id,$password,$id);$actors[$mode][$flow]=['token'=>$login['session_token'],'email'=>$email,'actor'=>$actor,'manager_actor'=>$mode==='integrated'?$id:null,'id'=>$login['account']['id'],'version'=>$login['account']['version']];
 }
 $socket=stream_socket_server('tcp://127.0.0.1:0');$port=(int)substr(strrchr(stream_socket_get_name($socket,false),':'),1);fclose($socket);$input=['root'=>$root,'origin'=>'http://127.0.0.1:'.$port,'control'=>bin2hex(random_bytes(32)),'password'=>$password,'accounts'=>$actors,'clubs'=>$clubs];$file=$root.'/browser.json';file_put_contents($file,json_encode($input,JSON_THROW_ON_ERROR));chmod($file,0600);putenv('DVM_EMAIL_ADDRESS_FIXTURE='.$file);$log=fopen($root.'/http.log','wb');$process=proc_open([...\Kulturhus\Native\TestSupport::phpCommand(),'-d','session.cookie_secure=0','-S','127.0.0.1:'.$port,'-t',$root.'/web',__DIR__.'/email-address-browser-router.php'],[0=>['pipe','r'],1=>$log,2=>$log],$pipes);fclose($pipes[0]);for($i=0;$i<100;$i++){$probe=@stream_socket_client('tcp://127.0.0.1:'.$port,$errno,$error,.1);if($probe){fclose($probe);break;}usleep(50000);}return['process'=>$process,'log'=>$log,'root'=>$root,'input'=>$input];
}
